133	void do_net_irq_mode(int mode)
134	{
135	    // turn on/off network driver's interrupt mode
136	    if(net_poll_mode != mode){
137	        assert(recv_transaction == 0);
138	        assert(send_transaction == 0);
139	        net_poll_mode = mode;
140	        if(net_poll_mode == 1){
141	            XEmacPs_IntEnable(&EmacPsInstance, (XEMACPS_IXR_TX_ERR_MASK | XEMACPS_IXR_RX_ERR_MASK |
142	                            (u32)XEMACPS_IXR_FRAMERX_MASK | (u32)XEMACPS_IXR_TXCOMPL_MASK));
