     9	/* Give up every binary semaphore `task` still holds and hand each of them to
    10	 * the next waiter, so that nobody stays blocked on a dead process. */
    11	static void release_binsem(pcb_t *task)
    12	{
    13	    while (task->binsem_num > 0) {
    14	        int id = task->binsem_id[--task->binsem_num];
    15	        binsem_node_t *node = &binsem_nodes[id];
    16	
    17	        node->sem++;
    18	        if (node->sem <= 0 && !list_empty(&node->block_queue)) {
    19	            list_node_t *heir_node = node->block_queue.next;
    20	            pcb_t *heir = list_entry(heir_node, pcb_t, list);
    21	            heir->binsem_id[heir->binsem_num++] = id;
    22	            do_unblock(heir_node);
    23	        }
    24	    }
    25	}
