    27	/* Common part of exiting and being killed: hand back the semaphores, wake
    28	 * everybody who waits for this task and disarm its sleep timer. */
    29	static void release_resources(pcb_t *task)
    30	{
    31	    release_binsem(task);
    32	
    33	    while (!list_empty(&task->wait_list)) {
    34	        do_unblock(task->wait_list.next);
    35	    }
    36	
    37	    /* a sleeping task may still have an armed timer */
    38	    list_del(&task->timer.list);
    39	}
