    41	/*
    42	 * Finish the teardown of a task whose address space is already gone.  The
    43	 * kernel stack is still in use at this point, so it is released later: either
    44	 * by the parent in do_waitpid() or by the idle task of core 0.
    45	 */
    46	static void reclaim_pcb(pcb_t *task)
    47	{
    48	    list_del(&task->list);
    49	
    50	    if (task->mode == ENTER_ZOMBIE_ON_EXIT) {
    51	        /* the parent reaps us in do_waitpid() */
    52	        task->status = TASK_ZOMBIE;
    53	    } else {
    54	        task->status = TASK_EXITED;
    55	        list_add_tail(&task->list, &kernel_pcb[0].wait_list);
    56	    }
    57	}
