    59	void do_exit()
    60	{
    61	    disable_preempt();
    62	    pcb_t *cur = current_running[cpu_id];
    63	
    64	    /* take ourselves out of the ready queue first: the wakeups below may
    65	     * reschedule, which must not put a dying task back */
    66	    list_del(&cur->list);
    67	    release_resources(cur);
    68	
    69	    /* We are still running on this address space, so scheduler() performs the
    70	     * teardown for us right after it has installed the next one. */
    71	    cur->status = TASK_KILLED;
    72	    scheduler();
    73	
    74	    enable_preempt();
    75	}
