    89	int do_kill(pid_t pid)
    90	{
    91	    disable_preempt();
    92	
    93	    pcb_t *victim = NULL;
    94	    for (int i = 0; i < NUM_MAX_TASK; i++) {
    95	        if (pcb[i].pid == pid) {
    96	            victim = &pcb[i];
