   100	    if (victim == NULL || victim->status == TASK_EXITED ||
   101	        victim->status == TASK_ZOMBIE || victim->status == TASK_KILLED) {
   102	        enable_preempt();
   103	        return 0;
   104	    }
   105	
   106	    if (victim == current_running[cpu_id]) {
   107	        /* killing ourselves is just an exit */
   108	        enable_preempt();
   109	        do_exit();
   110	        return 1;
   111	    }
   112	
   113	    release_resources(victim);
   114	
   115	    if (victim->status == TASK_RUNNING) {
   116	        /* it is running on the other hart, and its page table is live there:
   117	         * flag it and let that hart finish the teardown when it reschedules */
   118	        victim->status = TASK_KILLED;
   119	    } else {
   120	        free_process_user_page(victim->pgdir);
   121	        victim->pgdir = (PTE*)PGDIR_PA;
   122	        reclaim_pcb(victim);
   123	    }
   124	
   125	    enable_preempt();
   126	    return 1;
   127	}
