   129	/*
   130	 * A blocked process can only be resumed in user mode, so waitpid cannot
   131	 * simply continue where it left off.  Instead the caller is blocked on the
   132	 * child's wait list and `sepc` is rewound onto the `ecall`, so once the child
   133	 * exits the system call is executed again -- this time finding the child
   134	 * gone (or a zombie ready to be reaped).  The return value has to be `pid`
   135	 * in that case because handle_syscall() writes it back into a0, which is the
   136	 * very argument the retried `ecall` will pick up.
   137	 */
   138	int do_waitpid(pid_t pid, reg_t ignore1, reg_t ignore2, reg_t ignore3, regs_context_t *regs)
   139	{
   140	    disable_preempt();
   141	
   142	    pcb_t *child = NULL;
   143	    for (int i = 0; i < NUM_MAX_TASK; i++) {
   144	        if (pcb[i].pid == pid) {
   145	            child = &pcb[i];
   146	            break;
   147	        }
   148	    }
   149	
   150	    if (child == NULL) {
   151	        /* already gone and cleaned up */
   152	        enable_preempt();
   153	        return 0;
   154	    }
   155	
   156	    if (child->status == TASK_ZOMBIE || child->status == TASK_EXITED) {
   157	        /* reap it: release the kernel stack and free the pcb slot */
   158	        free_user_page(kva2pa(child->kernel_stack_base - PAGE_SIZE));
   159	        list_del(&child->list);
   160	        child->status = TASK_EXITED;
   161	        child->pid = -1;
   162	        enable_preempt();
   163	        return 1;
   164	    }
   165	
   166	    /* still alive: sleep on it and retry the system call when woken up */
   167	    regs->sepc = regs->sepc - 4;
   168	    do_block(&current_running[cpu_id]->list, &child->wait_list);
   169	    scheduler();
   170	
   171	    enable_preempt();
   172	    return pid;
   173	}
